  static const compact = UuText(
    headingLg: TextStyle(fontSize: 23.0, height: 1.3913, fontWeight: FontWeight.w600, letterSpacing: 0),
    headingBase: TextStyle(fontSize: 19.0, height: 1.4737, fontWeight: FontWeight.w600, letterSpacing: 0),
    headingSm: TextStyle(fontSize: 16.0, height: 1.5000, fontWeight: FontWeight.w600, letterSpacing: 0),
